DO $test$
DECLARE u uuid;bid uuid:=gen_random_uuid();plan uuid;emp uuid:=gen_random_uuid();lt uuid:=gen_random_uuid();tx uuid:=gen_random_uuid();calc uuid:=gen_random_uuid();run1 uuid;run2 uuid;rev timestamptz;entry jsonb;payload jsonb;duplicate_payload jsonb;empty_payload jsonb;r jsonb;denied boolean;
BEGIN
 IF public.frindly_market_environment_status()->>'project_ref' IS DISTINCT FROM 'smvvevrtjqkflyqkyape' THEN RAISE EXCEPTION 'Market only';END IF;
 SELECT id INTO u FROM auth.users a WHERE email_confirmed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=a.id) ORDER BY id LIMIT 1;SELECT id INTO plan FROM public.plans WHERE 'payroll'=ANY(included_modules) ORDER BY cardinality(included_modules) DESC NULLS LAST LIMIT 1;IF u IS NULL OR plan IS NULL THEN RAISE EXCEPTION 'Fixture prerequisites missing';END IF;
 BEGIN
  INSERT INTO public.businesses(id,name) VALUES(bid,'Market statutory consumption fixture');INSERT INTO public.profiles(id,business_id,active_business_id,full_name,role,is_super_admin) VALUES(u,bid,bid,'Consumption owner','owner',false);INSERT INTO public.business_memberships(business_id,user_id,role,status) VALUES(bid,u,'owner','active');INSERT INTO public.subscriptions(business_id,plan_id,status,current_period_end,trial_ends_at) VALUES(bid,plan,'trialing',now()+interval '30 days',now()+interval '30 days');INSERT INTO public.accounting_periods(business_id,period_start,period_end,financial_year,status) VALUES(bid,'2026-04-01','2027-03-31',2027,'open');INSERT INTO public.payroll_employees(id,business_id,employee_number,first_name,last_name,pay_type) VALUES(emp,bid,'CONSUME-1','Leave','Fixture','hourly');INSERT INTO public.payroll_leave_types(id,business_id,name,paid,statutory_leave_code) VALUES(lt,bid,'Sick leave fixture',true,'sick_leave');
  INSERT INTO public.payroll_leave_transactions(id,business_id,employee_id,leave_type_id,transaction_date,transaction_type,hours,statutory_quantity,statutory_unit,display_hours,statutory_leave_code,created_by) VALUES(tx,bid,emp,lt,'2026-10-05','taken',8,1,'days',8,'sick_leave',u);
  INSERT INTO public.payroll_statutory_leave_calculations(id,business_id,employee_id,leave_type_id,leave_transaction_id,statutory_leave_code,calculation_type,relevant_from,relevant_to,selected_method,selected_amount,confirmation_state,input_snapshot,explanation_snapshot,created_by,updated_by) VALUES(calc,bid,emp,lt,tx,'sick_leave','sick_leave','2026-10-05','2026-10-05','rdp',100,'confirmed','{"statutory_quantity":1,"statutory_unit":"days"}','{"status":"calculated","reasons":[]}',u,u);
  entry:=jsonb_build_object('employee_id',emp,'employee_snapshot',jsonb_build_object('name','Leave Fixture','employee_number','CONSUME-1'),'hours',0,'rate',0,'ordinary_earnings',0,'holiday_pay',0,'allowances',100,'reimbursements',0,'gross_pay',100,'paye',20,'kiwisaver_employee',0,'student_loan',0,'other_deductions',0,'total_deductions',20,'net_pay',80,'kiwisaver_employer_gross',0,'esct',0,'employer_contributions',0,'total_employment_cost',100,'calculation_snapshot',jsonb_build_object('statutory_leave',jsonb_build_array(jsonb_build_object('statutory_calculation_id',calc,'statutory_leave_code','sick_leave','quantity',1,'amount',100)),'p7_tax',jsonb_build_object('status','calculated')));
  payload:=jsonb_build_object('run',jsonb_build_object('pay_run_number','CONSUME-1','pay_frequency','weekly','period_start','2026-10-01','period_end','2026-10-07','pay_date','2026-10-08','country_code','NZ','currency','NZD','rules_snapshot','{}'::jsonb,'gross_pay',100,'total_deductions',20,'net_pay',80,'employer_contributions',0,'total_employment_cost',100),'employees',jsonb_build_array(jsonb_build_object('employee',entry,'lines',jsonb_build_array(jsonb_build_object('statutory_calculation_id',calc,'line_type','earning','description','Sick Leave','quantity',1,'rate',100,'amount',100,'taxable',true)),'payslip',NULL)),'financial','[]'::jsonb,'finalise',false);
  PERFORM set_config('request.jwt.claim.sub',u::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
  duplicate_payload:=jsonb_set(payload,'{employees,0,lines}',(payload#>'{employees,0,lines}')||jsonb_build_array(payload#>'{employees,0,lines,0}'));
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),NULL,NULL,duplicate_payload);EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'One pay run accepted the same statutory leave calculation twice';END IF;
  r:=public.v6226_save_pay_run(gen_random_uuid(),NULL,NULL,payload);run1:=(r->'run'->>'id')::uuid;rev:=(r->'run'->>'updated_at')::timestamptz;IF (SELECT pay_run_id FROM public.payroll_statutory_leave_calculations WHERE id=calc) IS DISTINCT FROM run1 THEN RAISE EXCEPTION 'Draft did not reserve confirmed leave';END IF;
  denied:=false;BEGIN PERFORM public.v6226_save_pay_run(gen_random_uuid(),NULL,NULL,jsonb_set(payload,'{run,pay_run_number}','"CONSUME-2"'));EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'A second run reused reserved leave';END IF;
  entry:=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(entry,'{allowances}','0'),'{gross_pay}','0'),'{total_deductions}','0'),'{net_pay}','0'),'{total_employment_cost}','0');entry:=jsonb_set(entry,'{calculation_snapshot,statutory_leave}','[]'::jsonb);
  empty_payload:=jsonb_build_object('run',jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload->'run','{gross_pay}','0'),'{total_deductions}','0'),'{net_pay}','0'),'{total_employment_cost}','0'),'{employer_contributions}','0'),'employees',jsonb_build_array(jsonb_build_object('employee',entry,'lines','[]'::jsonb,'payslip',NULL)),'financial','[]'::jsonb,'finalise',false);
  r:=public.v6226_save_pay_run(gen_random_uuid(),run1,rev,empty_payload);rev:=(r->'run'->>'updated_at')::timestamptz;IF (SELECT pay_run_id FROM public.payroll_statutory_leave_calculations WHERE id=calc) IS NOT NULL THEN RAISE EXCEPTION 'Removing draft line did not release leave';END IF;
  denied:=false;BEGIN INSERT INTO public.payroll_pay_run_lines(business_id,pay_run_employee_id,statutory_calculation_id,line_type,description,quantity,rate,amount,taxable) SELECT bid,id,calc,'earning','Bypass',1,100,100,true FROM public.payroll_pay_run_employees WHERE pay_run_id=run1 LIMIT 1;EXCEPTION WHEN insufficient_privilege THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'Direct statutory pay-line bypass succeeded';END IF;
  r:=public.v6226_save_pay_run(gen_random_uuid(),run1,rev,payload);IF (SELECT pay_run_id FROM public.payroll_statutory_leave_calculations WHERE id=calc) IS DISTINCT FROM run1 THEN RAISE EXCEPTION 'Edited draft did not reserve leave again';END IF;DELETE FROM public.payroll_pay_runs WHERE id=run1;IF (SELECT pay_run_id FROM public.payroll_statutory_leave_calculations WHERE id=calc) IS NOT NULL THEN RAISE EXCEPTION 'Deleting a draft did not release leave';END IF;
  payload:=jsonb_set(payload,'{finalise}','true');payload:=jsonb_set(payload,'{employees,0,payslip}',jsonb_build_object('number','CONSUME-2-CONSUME-1','data',jsonb_build_object('employee',jsonb_build_object('id',emp,'name','Leave Fixture'),'run',jsonb_build_object('number','CONSUME-2','period_start','2026-10-01','period_end','2026-10-07','pay_date','2026-10-08'),'pay',jsonb_build_object('gross',100,'net',80),'currency','NZD')));payload:=jsonb_set(payload,'{financial}',jsonb_build_array(jsonb_build_object('type','wage_expense','amount',100),jsonb_build_object('type','paye_payable','amount',20),jsonb_build_object('type','net_wages_payable','amount',80),jsonb_build_object('type','total_employment_cost','amount',100)));payload:=jsonb_set(payload,'{run,pay_run_number}','"CONSUME-2"');
  r:=public.v6226_save_pay_run(gen_random_uuid(),NULL,NULL,payload);run2:=(r->'run'->>'id')::uuid;IF r->'run'->>'status'<>'finalised' OR (SELECT pay_run_id FROM public.payroll_statutory_leave_calculations WHERE id=calc) IS DISTINCT FROM run2 THEN RAISE EXCEPTION 'Finalised run did not consume leave';END IF;
  PERFORM public.v61105_phase13b_reverse_pay_run(run2,'Fixture correction');IF (SELECT pay_run_id FROM public.payroll_statutory_leave_calculations WHERE id=calc) IS NOT NULL THEN RAISE EXCEPTION 'Reversal did not release leave';END IF;
  EXECUTE 'RESET ROLE';
  IF NOT EXISTS(SELECT 1 FROM public.payroll_statutory_leave_consumption_events WHERE calculation_id=calc AND pay_run_id=run2 AND action='reserved') OR NOT EXISTS(SELECT 1 FROM public.payroll_statutory_leave_consumption_events WHERE calculation_id=calc AND pay_run_id=run2 AND action='released') THEN RAISE EXCEPTION 'Finalised statutory leave reservation or reversal history is incomplete';END IF;
  RAISE EXCEPTION USING ERRCODE='P6232',MESSAGE='Rollback statutory consumption fixture';
 EXCEPTION WHEN SQLSTATE 'P6232' THEN NULL;END;
 IF EXISTS(SELECT 1 FROM public.businesses WHERE id=bid) OR EXISTS(SELECT 1 FROM public.payroll_statutory_leave_consumption_events WHERE calculation_id=calc) THEN RAISE EXCEPTION 'Statutory consumption fixture leaked';END IF;RAISE NOTICE 'Statutory leave pay-run consumption fixture passed; all data rolled back';
END;$test$;
